/* ════════════════════════════════════════════════
   EDITORIAL
   ════════════════════════════════════════════════ */
.editorial-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  grid-template-rows: auto;
  gap: 1.5rem;
}

/* First card spans full height (two rows on large screens) */
.editorial-grid > li:first-child {
  grid-row: span 2;
}

.editorial-card {
  position: relative;
  border-radius: var(--r-lg);
  overflow: hidden;
  background: var(--card-solid);
  border: 1px solid var(--border);
