}
.editorial-meta a {
  color: var(--accent-light);
  font-weight: 600;
  transition: color var(--t);
  display: inline-flex;
  align-items: center;
  gap: 0.2em;
}
.editorial-meta a:hover { color: var(--text-primary); }

/* ════════════════════════════════════════════════
   NEWSLETTER
   ════════════════════════════════════════════════ */
.newsletter-section {
  position: relative;
  overflow: hidden;
  padding-block: clamp(4rem, 8vw, 6rem);
  background: var(--surface);
  border-top: 1px solid var(--border);
}

.newsletter-glow {
  position: absolute;
  top: 50%; left: 50%;
  transform: translate(-50%, -50%);
  width: 600px; height: 300px;
  background: radial-gradient(ellipse, var(--accent-dim) 0%, transparent 70%);
  pointer-events: none;
}

.newsletter-inner {
