  z-index: 1;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
  align-items: center;
}

.newsletter-sub {
  color: var(--text-secondary);
  margin-top: 0.75rem;
  font-size: 0.95rem;
