+:root {
+  /* Colours */
+  --bg:             #09090f;
+  --surface:        #111119;
+  --card:           #16162280;
+  --card-solid:     #161622;
+  --card-hover:     #1d1d2e;
+  --border:         #25253a;
+  --border-bright:  #38385a;
+
+  --text-primary:   #edecf8;   /* ~14.5:1 on --bg */
+  --text-secondary: #b3b0d4;   /* ~7.2:1  on --bg */
+  --text-muted:     #7a779e;   /* ~4.6:1  on --bg */
+
+  --accent:         #8b5cf6;
+  --accent-light:   #a78bfa;
+  --accent-dim:     rgba(139, 92, 246, 0.18);
+  --accent-glow:    rgba(139, 92, 246, 0.35);
+
+  --deal:           #f97316;
+  --deal-light:     #fb923c;
+  --deal-dim:       rgba(249, 115, 22, 0.15);
+
+  --success:        #22c55e;
+  --danger:         #f87171;
+
+  /* Typography */
+  --font-display:   Georgia, 'Times New Roman', serif;
+  --font-body:      system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
+  --font-mono:      'Courier New', Courier, monospace;
+
+  /* Radii */
+  --r-sm:  6px;
+  --r-md:  12px;
+  --r-lg:  20px;
+  --r-xl:  28px;
+  --r-pill: 9999px;
+
+  /* Shadows */
+  --shadow-sm:    0 2px 8px rgba(0, 0, 0, 0.35);
+  --shadow-card:  0 4px 24px rgba(0, 0, 0, 0.5);
+  --shadow-hover: 0 8px 40px rgba(0, 0, 0, 0.65), 0 0 0 1px var(--border-bright);
+  --shadow-accent:0 0 32px var(--accent-glow);
+
+  /* Layout */
+  --container:     1280px;
+  --pad:           clamp(1rem, 4vw, 2rem);
+
+  /* Transitions */
+  --t:    200ms ease;
+  --t-lg: 350ms ease;
+}
+
+/* ─── Reset & Base ───────────────────────────── */
+*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
+
+html {
+  scroll-behavior: smooth;
+  color-scheme: dark;
+}
+
+body {
+  font-family: var(--font-body);
+  background-color: var(--bg);
+  color: var(--text-primary);
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+  overflow-x: hidden;
+}
+
+img {
+  display: block;
+  max-width: 100%;
+  height: auto;
+}
+
+a { color: inherit; text-decoration: none; }
+ul { list-style: none; }
+button { cursor: pointer; border: none; background: none; font: inherit; color: inherit; }
+
+/* ─── Focus Styles ───────────────────────────── */
+:focus-visible {
+  outline: 2px solid var(--accent-light);
+  outline-offset: 3px;
+  border-radius: var(--r-sm);
+}
+
+/* ─── Skip Link ──────────────────────────────── */
+.skip-link {
+  position: fixed;
+  top: -100%;
+  left: 1rem;
+  z-index: 9999;
+  padding: 0.6em 1.2em;
+  background: var(--accent);
+  color: #fff;
+  font-weight: 600;
+  border-radius: 0 0 var(--r-md) var(--r-md);
+  transition: top var(--t);
+}
+.skip-link:focus { top: 0; }
+
+/* ─── Utility ────────────────────────────────── */
+.sr-only {
+  position: absolute;
+  width: 1px; height: 1px;
+  padding: 0; margin: -1px;
+  overflow: hidden;
+  clip: rect(0,0,0,0);
+  white-space: nowrap;
+  border: 0;
+}
+
+.container {
+  width: 100%;
+  max-width: var(--container);
+  margin-inline: auto;
+  padding-inline: var(--pad);
+}
+
+/* ─── Typography helpers ─────────────────────── */
+.eyebrow {
+  font-size: 0.72rem;
+  font-weight: 700;
+  letter-spacing: 0.12em;
+  text-transform: uppercase;
+  color: var(--accent-light);
+}
+.section-title {
+  font-size: clamp(1.6rem, 3.5vw, 2.4rem);
+  font-weight: 700;
+  line-height: 1.2;
+  margin-top: 0.3em;
+}
+
+/* ─── Buttons ────────────────────────────────── */
+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: 0.5em;
+  padding: 0.75em 1.6em;
+  font-size: 0.9rem;
+  font-weight: 600;
+  border-radius: var(--r-pill);
+  transition: background var(--t), transform var(--t), box-shadow var(--t);
+  white-space: nowrap;
+  border: 2px solid transparent;
+}
+.btn:hover { transform: translateY(-1px); }
+.btn:active { transform: translateY(0); }
+
+.btn-primary {
+  background: var(--accent);
+  color: #fff;
+  border-color: var(--accent);
+}
+.btn-primary:hover {
+  background: var(--accent-light);
+  border-color: var(--accent-light);
+  box-shadow: 0 6px 24px var(--accent-glow);
+}
+
+.btn-ghost {
+  background: transparent;
+  color: var(--text-primary);
+  border-color: var(--border-bright);
+}
+.btn-ghost:hover {
+  background: rgba(255,255,255,0.06);
+  border-color: var(--text-muted);
+}
+
+.btn-deal {
+  background: var(--deal);
+  color: #fff;
+  border-color: var(--deal);
+}
+.btn-deal:hover {
+  background: var(--deal-light);
+  border-color: var(--deal-light);
+  box-shadow: 0 6px 24px rgba(249,115,22,0.4);
+}
+
+.btn-sm {
+  padding: 0.5em 1.1em;
+  font-size: 0.8rem;
+}
+
+.icon-btn {
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  width: 40px;
+  height: 40px;
+  border-radius: var(--r-md);
+  color: var(--text-secondary);
+  transition: color var(--t), background var(--t);
+  position: relative;
+  flex-shrink: 0;
+}
+.icon-btn:hover { color: var(--text-primary); background: rgba(255,255,255,0.06); }
+
+/* ─── Link arrow ─────────────────────────────── */
+.link-arrow {
+  font-size: 0.875rem;
+  font-weight: 600;
+  color: var(--accent-light);
+  display: inline-flex;
+  align-items: center;
+  gap: 0.3em;
+  transition: gap var(--t), color var(--t);
+  white-space: nowrap;
+}
+.link-arrow:hover { gap: 0.6em; color: var(--text-primary); }
+
+/* ─── Section scaffolding ────────────────────── */
+.section { padding-block: clamp(3rem, 8vw, 6rem); }
+
+.section-header {
+  display: flex;
+  align-items: flex-end;
+  justify-content: space-between;
+  gap: 1rem;
+  margin-bottom: 2.5rem;
+}
+
+/* ════════════════════════════════════════════════
+   HEADER
+   ════════════════════════════════════════════════ */
+.site-header {
+  position: sticky;
+  top: 0;
+  z-index: 100;
+  background: rgba(9, 9, 15, 0.82);
+  backdrop-filter: blur(20px);
+  -webkit-backdrop-filter: blur(20px);
+  border-bottom: 1px solid var(--border);
+}
+
+.header-inner {
+  display: flex;
+  align-items: center;
+  gap: 1.5rem;
+  height: 64px;
+}
+
+.logo {
+  display: flex;
+  align-items: center;
+  gap: 0.6em;
+  font-size: 1.05rem;
+  font-weight: 800;
+  letter-spacing: 0.15em;
+  color: var(--text-primary);
+  flex-shrink: 0;
+  transition: color var(--t);
+}
+.logo:hover { color: var(--accent-light); }
+.logo-mark { color: var(--accent); }
+
+.main-nav { margin-inline-start: auto; }
+.main-nav ul { display: flex; align-items: center; gap: 0.25rem; }
+.main-nav a {
+  padding: 0.4em 0.75em;
+  font-size: 0.875rem;
+  font-weight: 500;
+  color: var(--text-secondary);
+  border-radius: var(--r-sm);
+  transition: color var(--t), background var(--t);
+}
+.main-nav a:hover { color: var(--text-primary); background: rgba(255,255,255,0.06); }
+
+.header-actions { display: flex; align-items: center; gap: 0.25rem; margin-inline-start: auto; }
+
+.cart-badge {
+  position: absolute;
+  top: 4px; right: 4px;
+  width: 18px; height: 18px;
+  border-radius: 50%;
+  background: var(--accent);
+  color: #fff;
+  font-size: 0.65rem;
+  font-weight: 700;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  pointer-events: none;
+  line-height: 1;
+}
+
+.mobile-menu-btn { display: none; }
+
+.mobile-nav {
+  border-top: 1px solid var(--border);
+  background: var(--surface);
+  padding: 1rem var(--pad);
+}
+.mobile-nav ul { display: flex; flex-direction: column; gap: 0.25rem; }
+.mobile-nav a {
+  display: block;
+  padding: 0.6em 0.75em;
+  font-size: 0.95rem;
+  font-weight: 500;
+  color: var(--text-secondary);
+  border-radius: var(--r-sm);
+  transition: color var(--t), background var(--t);
+}
+.mobile-nav a:hover { color: var(--text-primary); background: rgba(255,255,255,0.06); }
+
+/* ════════════════════════════════════════════════
+   HERO
+   ════════════════════════════════════════════════ */
+.hero {
+  position: relative;
+  min-height: clamp(520px, 85vh, 800px);
+  display: flex;
+  align-items: center;
+  overflow: hidden;
+}
+
+.hero-bg {
+  position: absolute;
+  inset: 0;
+  pointer-events: none;
+}
+
+.hero-orb {
+  position: absolute;
+  border-radius: 50%;
+  filter: blur(80px);
+  opacity: 0.55;
+}
+.hero-orb--1 {
+  width: 700px; height: 700px;
+  top: -200px; right: -150px;
+  background: radial-gradient(circle, rgba(139,92,246,0.45) 0%, transparent 70%);
+  animation: float 8s ease-in-out infinite;
+}
+.hero-orb--2 {
+  width: 500px; height: 500px;
+  bottom: -180px; left: -80px;
+  background: radial-gradient(circle, rgba(99,68,180,0.3) 0%, transparent 70%);
+  animation: float 11s ease-in-out infinite reverse;
+}
+
+.hero-grid-lines {
+  position: absolute;
+  inset: 0;
+  background-image:
+    linear-gradient(rgba(139,92,246,0.05) 1px, transparent 1px),
+    linear-gradient(90deg, rgba(139,92,246,0.05) 1px, transparent 1px);
+  background-size: 60px 60px;
+  mask-image: radial-gradient(ellipse 80% 80% at 50% 50%, black 40%, transparent 100%);
+}
+
+@keyframes float {
+  0%, 100% { transform: translateY(0) scale(1); }
+  50%       { transform: translateY(-30px) scale(1.05); }
+}
+
+.hero-content {
+  position: relative;
+  z-index: 1;
+  padding-block: 5rem 4rem;
+  max-width: 680px;
+}
+
+.hero-eyebrow { margin-bottom: 1.2rem; }
+
+.hero-heading {
+  font-family: var(--font-display);
+  font-size: clamp(2.8rem, 7vw, 5.5rem);
+  font-weight: 700;
+  line-height: 1.08;
+  letter-spacing: -0.02em;
+  color: var(--text-primary);
+  margin-bottom: 1.2rem;
+}
+.hero-heading em {
+  font-style: italic;
+  background: linear-gradient(135deg, var(--accent-light) 0%, #c4b5fd 100%);
+  -webkit-background-clip: text;
+  -webkit-text-fill-color: transparent;
+  background-clip: text;
+}
+
+.hero-sub {
+  font-size: clamp(1rem, 2vw, 1.2rem);
+  color: var(--text-secondary);
+  margin-bottom: 2.5rem;
+  max-width: 480px;
+}
+
+.hero-actions { display: flex; flex-wrap: wrap; gap: 0.75rem; margin-bottom: 3.5rem; }
+
+.hero-stats {
+  display: flex;
+  gap: clamp(1.5rem, 4vw, 3rem);
+  padding-top: 2rem;
+  border-top: 1px solid var(--border);
+}
+.hero-stat { display: flex; flex-direction: column; }
+.hero-stat-value {
+  font-size: 1.6rem;
+  font-weight: 800;
+  color: var(--text-primary);
+  line-height: 1;
+}
+.hero-stat-label {
+  font-size: 0.78rem;
+  color: var(--text-muted);
+  margin-top: 0.25em;
+}
+
+/* ════════════════════════════════════════════════
+   CATEGORY STRIP
+   ════════════════════════════════════════════════ */
+.category-strip {
+  border-block: 1px solid var(--border);
+  background: var(--surface);
+  padding-block: 1rem;
+}
+
+.category-list {
+  display: flex;
+  gap: 0.5rem;
+  overflow-x: auto;
+  scrollbar-width: none;
+  -ms-overflow-style: none;
+  padding-block: 0.25rem;
+}
+.category-list::-webkit-scrollbar { display: none; }
+
+.category-chip {
+  padding: 0.45em 1.1em;
+  font-size: 0.82rem;
+  font-weight: 600;
+  border-radius: var(--r-pill);
+  border: 1px solid var(--border);
+  color: var(--text-secondary);
+  background: transparent;
+  transition: color var(--t), background var(--t), border-color var(--t);
+  white-space: nowrap;
+}
+.category-chip:hover {
+  color: var(--text-primary);
+  border-color: var(--border-bright);
+  background: rgba(255,255,255,0.05);
+}
+.category-chip.active {
+  background: var(--accent);
+  border-color: var(--accent);
+  color: #fff;
+}
+
+/* ════════════════════════════════════════════════
+   PRODUCT GRID
+   ════════════════════════════════════════════════ */
+.product-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(min(100%, 240px), 1fr));
+  gap: 1.5rem;
+}
+
+.product-card {
+  background: var(--card-solid);
+  border: 1px solid var(--border);
+  border-radius: var(--r-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color var(--t), box-shadow var(--t-lg), transform var(--t-lg);
+  position: relative;
+}
+.product-card:hover {
+  border-color: var(--border-bright);
+  box-shadow: var(--shadow-hover);
+  transform: translateY(-4px);
+}
+
+.product-img-wrap {
+  position: relative;
+  aspect-ratio: 4 / 5;
+  background: var(--surface);
+  overflow: hidden;
+}
+.product-img-wrap img {
+  width: 100%; height: 100%;
+  object-fit: cover;
+  transition: transform var(--t-lg);
+}
+.product-card:hover .product-img-wrap img { transform: scale(1.04); }
+
+.product-badge {
+  position: absolute;
+  top: 0.75rem; left: 0.75rem;
+  padding: 0.25em 0.65em;
+  font-size: 0.68rem;
+  font-weight: 700;
+  letter-spacing: 0.06em;
+  text-transform: uppercase;
+  border-radius: var(--r-sm);
+  z-index: 1;
+}
+.product-badge--new    { background: var(--accent); color: #fff; }
+.product-badge--sale   { background: var(--deal); color: #fff; }
+.product-badge--hot    { background: #ef4444; color: #fff; }
+
+.product-wishlist {
+  position: absolute;
+  top: 0.75rem; right: 0.75rem;
+  width: 34px; height: 34px;
+  border-radius: 50%;
+  background: rgba(9, 9, 15, 0.7);
+  backdrop-filter: blur(8px);
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  color: var(--text-secondary);
+  transition: color var(--t), background var(--t), transform var(--t);
+  border: 1px solid var(--border);
+  z-index: 1;
+  opacity: 0;
+  transform: scale(0.8);
+}
+.product-card:hover .product-wishlist,
+.product-card:focus-within .product-wishlist {
+  opacity: 1;
+  transform: scale(1);
+}
+.product-wishlist:hover { color: #f87171; background: rgba(9, 9, 15, 0.9); }
+.product-wishlist.active { color: #f87171; }
+.product-wishlist:focus-visible { opacity: 1; transform: scale(1); }
+
+.product-body {
+  padding: 1.1rem;
+  display: flex;
+  flex-direction: column;
+  flex: 1;
+  gap: 0.5rem;
+}
+
+.product-category {
+  font-size: 0.7rem;
+  font-weight: 700;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+}
+
+.product-name {
+  font-size: 0.95rem;
+  font-weight: 600;
+  color: var(--text-primary);
+  line-height: 1.35;
+}
+
+.product-rating {
+  display: flex;
+  align-items: center;
+  gap: 0.4em;
+  font-size: 0.78rem;
+  color: var(--text-muted);
+}
+.stars { color: #f59e0b; letter-spacing: -0.05em; }
+
+.product-price-row {
+  display: flex;
+  align-items: baseline;
+  gap: 0.5em;
+  margin-top: auto;
+}
+.product-price {
+  font-size: 1.1rem;
+  font-weight: 700;
+  color: var(--text-primary);
+}
+.product-price-original {
+  font-size: 0.85rem;
+  color: var(--text-muted);
+  text-decoration: line-through;
+}
+.product-price-save {
+  font-size: 0.75rem;
+  font-weight: 700;
+  color: var(--success);
+}
+
+.product-actions {
+  padding: 0 1.1rem 1.1rem;
+}
+.add-to-cart {
+  width: 100%;
+  justify-content: center;
+  border-radius: var(--r-md);
+}
+
+/* ════════════════════════════════════════════════
+   DEALS SECTION
+   ════════════════════════════════════════════════ */
+.deals-section { background: var(--surface); }
+
+.deals-banner {
+  display: flex;
+  align-items: center;
+  justify-content: space-between;
+  gap: 2rem;
+  padding: 2rem 2.5rem;
+  background: linear-gradient(135deg, rgba(249,115,22,0.1) 0%, rgba(249,115,22,0.03) 100%);
+  border: 1px solid rgba(249,115,22,0.25);
+  border-radius: var(--r-xl);
+  margin-bottom: 2rem;
+  flex-wrap: wrap;
+}
+
+.deals-eyebrow { color: var(--deal-light); }
+
+.deals-sub {
+  color: var(--text-secondary);
+  margin-top: 0.5rem;
+  font-size: 0.95rem;
+}
+
+.countdown { text-align: right; }
+.countdown-label {
+  font-size: 0.72rem;
+  font-weight: 700;
+  letter-spacing: 0.1em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  margin-bottom: 0.5rem;
+}
+
+.countdown-timer {
+  display: flex;
+  align-items: center;
+  gap: 0.4rem;
+}
+
+.countdown-unit {
+  display: flex;
+  flex-direction: column;
+  align-items: center;
+  background: rgba(249,115,22,0.15);
+  border: 1px solid rgba(249,115,22,0.3);
+  border-radius: var(--r-md);
+  padding: 0.4em 0.75em;
+  min-width: 60px;
+}
+
+.countdown-num {
+  font-size: 1.8rem;
+  font-weight: 800;
+  font-variant-numeric: tabular-nums;
+  color: var(--deal-light);
+  line-height: 1;
+}
+
+.countdown-unit-label {
+  font-size: 0.65rem;
+  font-weight: 600;
+  letter-spacing: 0.08em;
+  text-transform: uppercase;
+  color: var(--text-muted);
+  margin-top: 0.2em;
+}
+
+.countdown-sep {
+  font-size: 1.6rem;
+  font-weight: 800;
+  color: var(--deal);
+  line-height: 1;
+  margin-bottom: 0.6em;
+}
+
+/* Deals grid — 4 columns, horizontal cards */
+.deals-grid {
+  display: grid;
+  grid-template-columns: repeat(auto-fill, minmax(min(100%, 260px), 1fr));
+  gap: 1.25rem;
+}
+
+.deal-card {
+  background: var(--card-solid);
+  border: 1px solid var(--border);
+  border-radius: var(--r-lg);
+  overflow: hidden;
+  display: flex;
+  flex-direction: column;
+  transition: border-color var(--t), box-shadow var(--t-lg), transform var(--t-lg);
+  position: relative;
+}
+.deal-card:hover {
+  border-color: rgba(249,115,22,0.4);
+  box-shadow: 0 8px 32px rgba(249,115,22,0.15), 0 0 0 1px rgba(249,115,22,0.3);
+  transform: translateY(-4px);
+}
+
+.deal-img-wrap {
+  position: relative;
+  aspect-ratio: 16 / 10;
+  background: var(--surface);
+  overflow: hidden;
+}
+.deal-img-wrap img {
+  width: 100%; height: 100%;
+  object-fit: cover;
+  transition: transform var(--t-lg);
+}
+.deal-card:hover .deal-img-wrap img { transform: scale(1.05); }
+
+.deal-discount-badge {
+  position: absolute;
+  bottom: 0.75rem; left: 0.75rem;
+  background: var(--deal);
+  color: #fff;
+  font-size: 0.85rem;
+  font-weight: 800;
+  padding: 0.2em 0.6em;
+  border-radius: var(--r-sm);
+  z-index: 1;
+}
+
+.deal-body {
+  padding: 1rem 1.1rem;
+  display: flex;
+  flex-direction: column;
+  gap: 0.4rem;
+  flex: 1;
+}
+
+.deal-name {
+  font-size: 0.92rem;
+  font-weight: 600;
+  color: var(--text-primary);
+}
+
+.deal-price-row {
+  display: flex;
+  align-items: baseline;
+  gap: 0.5em;
+  margin-top: 0.25rem;
+}
+.deal-price { font-size: 1.15rem; font-weight: 800; color: var(--deal-light); }
+.deal-price-orig { font-size: 0.85rem; color: var(--text-muted); text-decoration: line-through; }
+
