// ─── State ────────────────────────────────────

const state = {
  cart: [],         // [{ id, name, price, qty }]
  wishlist: new Set(),
  activeFilter: 'all',
};

// ─── Helpers ──────────────────────────────────

function formatPrice(n) {
  return '$' + n.toFixed(2).replace(/\.00$/, '');
}

function renderStars(rating) {
  const full  = Math.floor(rating);
  const half  = rating % 1 >= 0.5 ? 1 : 0;
  const empty = 5 - full - half;
  return '★'.repeat(full) + (half ? '½' : '') + '☆'.repeat(empty);
}

function calcSavings(price, originalPrice) {
  if (!originalPrice) return null;
  return Math.round((1 - price / originalPrice) * 100);
}

// ─── Product Cards ────────────────────────────

function buildProductCard(product) {
  const savings = calcSavings(product.price, product.originalPrice);
  const inWishlist = state.wishlist.has(product.id);
  const badgeHtml = product.badge
    ? `<span class="product-badge product-badge--${product.badgeType}">${product.badge}</span>`
    : '';

  return `
    <li>
      <article class="product-card" data-id="${product.id}" data-category="${product.category}">
        <div class="product-img-wrap">
          <img
            src="https://picsum.photos/seed/${product.imgSeed}/400/500"
            alt="${product.imgAlt}"
            loading="lazy"
            width="400"
            height="500"
          >
          ${badgeHtml}
          <button
            class="product-wishlist${inWishlist ? ' active' : ''}"
            aria-label="${inWishlist ? 'Remove' : 'Add'} ${product.name} from wishlist"
            aria-pressed="${inWishlist}"
            data-wishlist="${product.id}"
          >
            <svg width="16" height="16" viewBox="0 0 24 24" fill="${inWishlist ? 'currentColor' : 'none'}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">
              <path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"/>
            </svg>
          </button>
        </div>
        <div class="product-body">
          <p class="product-category">${product.categoryLabel}</p>
          <h3 class="product-name">${product.name}</h3>
          <div class="product-rating">
            <span class="stars" aria-hidden="true">${renderStars(product.rating)}</span>
            <span>${product.rating} (${product.reviewCount.toLocaleString()})</span>
          </div>
          <div class="product-price-row">
            <span class="product-price">${formatPrice(product.price)}</span>
            ${product.originalPrice ? `<span class="product-price-original" aria-label="Was ${formatPrice(product.originalPrice)}">${formatPrice(product.originalPrice)}</span>` : ''}
            ${savings ? `<span class="product-price-save">Save ${savings}%</span>` : ''}
          </div>
        </div>
        <div class="product-actions">
          <button class="btn btn-primary btn-sm add-to-cart" data-add="${product.id}">
