          <div class="editorial-meta">
            <span>${article.author} · ${article.readTime}</span>
            <a href="#" aria-label="Read ${article.title}">
              Read more
              <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M5 12h14M12 5l7 7-7 7"/></svg>
            </a>
          </div>
        </div>
      </article>
    </li>`;
}

// ─── Render ───────────────────────────────────

function renderProducts(filter = 'all') {
  const grid = document.getElementById('product-grid');
  if (!grid) return;
  const items = filter === 'all'
    ? PRODUCTS
    : PRODUCTS.filter(p => p.category === filter);

  if (items.length === 0) {
    grid.innerHTML = `<li style="grid-column:1/-1;text-align:center;padding:3rem;color:var(--text-muted);">No products found in this category.</li>`;
    return;
  }
  grid.innerHTML = items.map(buildProductCard).join('');
}

function renderDeals() {
  const grid = document.getElementById('deals-grid');
  if (grid) grid.innerHTML = DEALS.map(buildDealCard).join('');
}

function renderEditorial() {
  const grid = document.getElementById('editorial-grid');
  if (grid) grid.innerHTML = EDITORIAL.map(buildEditorialCard).join('');
}

// ─── Cart ─────────────────────────────────────

function getCartTotal() {
  return state.cart.reduce((sum, item) => sum + item.qty, 0);
}

function updateCartUI() {
  const btn   = document.getElementById('cart-btn');
  const badge = document.getElementById('cart-badge');
  const total = getCartTotal();

  if (btn)   btn.setAttribute('aria-label', `Cart, ${total} item${total !== 1 ? 's' : ''}`);
  if (badge) {
    badge.textContent = total;
    badge.hidden = total === 0;
  }
}

function addToCart(id, name, price) {
  const existing = state.cart.find(i => i.id === id);
  if (existing) {
    existing.qty += 1;
  } else {
    state.cart.push({ id, name, price, qty: 1 });
  }
  updateCartUI();
  showToast(`<strong>${name}</strong> added to cart.`, 'success');
  announce(`${name} added to cart.`);
}

// ─── Wishlist ─────────────────────────────────

function toggleWishlist(id, name, btn) {
  const inList = state.wishlist.has(id);
  if (inList) {
    state.wishlist.delete(id);
    btn.setAttribute('aria-pressed', 'false');
    btn.setAttribute('aria-label', `Add ${name} from wishlist`);
    btn.classList.remove('active');
    const path = btn.querySelector('path');
    if (path) path.setAttribute('fill', 'none');
    showToast(`Removed from wishlist.`, 'info');
  } else {
    state.wishlist.add(id);
    btn.setAttribute('aria-pressed', 'true');
    btn.setAttribute('aria-label', `Remove ${name} from wishlist`);
    btn.classList.add('active');
    const path = btn.querySelector('path');
    if (path) path.setAttribute('fill', 'currentColor');
    showToast(`<strong>${name}</strong> added to wishlist.`, 'info');
  }
}

// ─── Toast Notifications ──────────────────────

function showToast(html, type = 'info') {
  const container = document.getElementById('toast-container');
  if (!container) return;

  const icons = {
    success: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M20 6L9 17l-5-5"/></svg>`,
    error:   `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>`,
    info:    `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="8"/><line x1="12" y1="12" x2="12" y2="16"/></svg>`,
  };

  const toast = document.createElement('div');
  toast.className = `toast toast--${type}`;
  toast.innerHTML = `<span class="toast-icon">${icons[type] || icons.info}</span><span>${html}</span>`;
  container.appendChild(toast);

  // Remove after 3.5 s
  const removeToast = () => {
    toast.classList.add('toast--exit');
    toast.addEventListener('animationend', () => toast.remove(), { once: true });
  };
  const timer = setTimeout(removeToast, 3500);
  toast.addEventListener('click', () => { clearTimeout(timer); removeToast(); });
}

// ─── Screen-reader announcement ───────────────

function announce(msg) {
  const el = document.getElementById('live-announce');
  if (!el) return;
  el.textContent = '';
  // Allow double-announcements by forcing a reflow
  void el.offsetWidth;
  el.textContent = msg;
}

// ─── Countdown Timer ──────────────────────────

function initCountdown() {
  // Target = midnight tonight
  function getTarget() {
    const t = new Date();
    t.setHours(23, 59, 59, 999);
    return t;
  }

  const elH = document.getElementById('cd-hours');
  const elM = document.getElementById('cd-mins');
  const elS = document.getElementById('cd-secs');
  if (!elH || !elM || !elS) return;

  let target = getTarget();

  function pad(n) { return String(n).padStart(2, '0'); }

  function tick() {
    const now = Date.now();
    let diff = Math.max(0, target - now);

    if (diff === 0) {
      target = getTarget(); // reset to next day if needed
      return;
    }

    const h = Math.floor(diff / 3_600_000);
    diff -= h * 3_600_000;
    const m = Math.floor(diff / 60_000);
    diff -= m * 60_000;
    const s = Math.floor(diff / 1_000);

    elH.textContent = pad(h);
    elM.textContent = pad(m);
    elS.textContent = pad(s);
  }

  tick();
  setInterval(tick, 1000);
}

// ─── Category Filter ──────────────────────────

function initCategoryFilter() {
  document.querySelectorAll('.category-chip').forEach(btn => {
    btn.addEventListener('click', () => {
      const filter = btn.dataset.filter;
      state.activeFilter = filter;

      // Update button states
      document.querySelectorAll('.category-chip').forEach(b => {
        const isActive = b.dataset.filter === filter;
        b.classList.toggle('active', isActive);
        b.setAttribute('aria-pressed', String(isActive));
      });

      renderProducts(filter);
    });
  });
}

// ─── Event Delegation ─────────────────────────

function initEventDelegation() {
  // Product grid: add to cart + wishlist
  const productGrid = document.getElementById('product-grid');
  if (productGrid) {
    productGrid.addEventListener('click', e => {
      // Add to cart
      const addBtn = e.target.closest('[data-add]');
      if (addBtn && addBtn.closest('#product-grid')) {
        const id = addBtn.dataset.add;
        const product = PRODUCTS.find(p => p.id === id);
        if (product) addToCart(product.id, product.name, product.price);
        return;
      }

      // Wishlist
      const wishBtn = e.target.closest('[data-wishlist]');
      if (wishBtn) {
        const id = wishBtn.dataset.wishlist;
        const product = PRODUCTS.find(p => p.id === id);
        if (product) toggleWishlist(product.id, product.name, wishBtn);
      }
    });
  }

  // Deals grid: add to cart
  const dealsGrid = document.getElementById('deals-grid');
  if (dealsGrid) {
    dealsGrid.addEventListener('click', e => {
      const addBtn = e.target.closest('[data-add]');
      if (addBtn) {
        const id   = addBtn.dataset.add;
        const name = addBtn.dataset.name;
        const price = parseFloat(addBtn.dataset.price);
        addToCart(id, name, price);
      }
    });
  }
}

// ─── Mobile Menu ──────────────────────────────

function initMobileMenu() {
  const menuBtn = document.getElementById('menu-btn');
  const mobileNav = document.getElementById('mobile-nav');
  if (!menuBtn || !mobileNav) return;

  menuBtn.addEventListener('click', () => {
    const expanded = menuBtn.getAttribute('aria-expanded') === 'true';
    menuBtn.setAttribute('aria-expanded', String(!expanded));
    mobileNav.hidden = expanded;

    // Swap icon
    const icon = document.getElementById('menu-icon');
    if (icon) {
      icon.innerHTML = expanded
        ? `<line x1="3" y1="6" x2="21" y2="6"/><line x1="3" y1="12" x2="21" y2="12"/><line x1="3" y1="18" x2="21" y2="18"/>`
        : `<line x1="3" y1="6" x2="21" y2="18"/><line x1="3" y1="18" x2="21" y2="6"/>`;
    }
  });

  // Close menu on nav link click (mobile)
  mobileNav.querySelectorAll('a').forEach(a => {
    a.addEventListener('click', () => {
      mobileNav.hidden = true;
      menuBtn.setAttribute('aria-expanded', 'false');
    });
  });

  // Close on Escape
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && !mobileNav.hidden) {
      mobileNav.hidden = true;
      menuBtn.setAttribute('aria-expanded', 'false');
      menuBtn.focus();
    }
  });
}

// ─── Newsletter Form ──────────────────────────

function initNewsletter() {
  const form     = document.getElementById('newsletter-form');
  const input    = document.getElementById('email-input');
  const errorEl  = document.getElementById('email-error');
  if (!form || !input || !errorEl) return;

  function setError(msg) {
    errorEl.textContent = msg;
    errorEl.hidden = !msg;
    input.setAttribute('aria-invalid', msg ? 'true' : 'false');
  }

  form.addEventListener('submit', e => {
    e.preventDefault();
    const val = input.value.trim();

    if (!val) {
      setError('Please enter your email address.');
      input.focus();
      return;
    }
    // Basic email pattern check
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(val)) {
      setError('Please enter a valid email address (e.g. you@example.com).');
      input.focus();
      return;
    }

    setError('');
    showToast('You\'re subscribed! Welcome to OBSIDIAN.', 'success');
    announce('You have successfully subscribed to the OBSIDIAN newsletter.');
    form.reset();
  });

  // Clear error on input
  input.addEventListener('input', () => {
    if (input.getAttribute('aria-invalid') === 'true') {
      setError('');
    }
  });
}

// ─── Sticky Header Shadow ─────────────────────

function initStickyHeader() {
  const header = document.querySelector('.site-header');
  if (!header) return;
  const observer = new IntersectionObserver(
    ([entry]) => header.classList.toggle('scrolled', !entry.isIntersecting),
    { rootMargin: '-1px 0px 0px 0px' }
  );
  // Sentinel at top of page
  const sentinel = document.createElement('div');
  sentinel.style.cssText = 'position:absolute;top:0;height:1px;width:1px;pointer-events:none;';
  document.body.prepend(sentinel);
  observer.observe(sentinel);
}

// ─── Boot ─────────────────────────────────────

document.addEventListener('DOMContentLoaded', () => {
  renderProducts();
  renderDeals();
  renderEditorial();
  initCountdown();
  initCategoryFilter();
  initEventDelegation();
  initMobileMenu();
  initNewsletter();
  initStickyHeader();
});

